export const meta = {
  name: 'understand-swiftmandarin',
  description: 'Parallel deep read of all SwiftMandarin Swift files, mapped by subsystem with issues flagged against the user request',
  phases: [
    { title: 'Read', detail: 'parallel readers per subsystem' },
    { title: 'Synthesize', detail: 'merge into architecture map + prioritized issue list' },
  ],
}

const ROOT = '/Users/rogerlin/XCode-Projects/SwiftMandarinShortcuts/SwiftMandarin'

const USER_REQUEST = `
The user wants three things fixed/added in this app:
(A) The PHOTO UPLOAD / OCR feature often produces GIBBERISH, and it CANNOT switch languages — it seems stuck detecting English and cannot read Mandarin/Chinese. Find the root cause in the OCR + language-detection + recognition-level pipeline.
(B) EXPAND AI model providers beyond Ollama to include OpenAI, Claude (Anthropic), Deepseek, Doubao (ByteDance), Qwen (Alibaba/DashScope), Kimi (Moonshot), Zhipu (GLM), Minimax, etc., and PULL the available model list from each provider's API.
(C) DEEPLY INTEGRATE AI: e.g. a settings toggle that, when ON, routes an uploaded photo to an AI vision/text model for cleanup and returns cleaned/structured text to the app.
When reading, flag anything relevant to A, B, or C: OCR config, Vision recognitionLanguages, NLLanguageRecognizer usage, AI provider abstractions, model settings, API key storage, request building, and integration seams.
`

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['subsystem', 'files', 'keyTypes', 'dataFlow', 'issues', 'integrationPoints'],
  properties: {
    subsystem: { type: 'string' },
    files: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['path', 'purpose'],
        properties: { path: { type: 'string' }, purpose: { type: 'string' } },
      },
    },
    keyTypes: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['name', 'kind', 'responsibility'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', description: 'struct|class|enum|protocol|actor|extension' },
          responsibility: { type: 'string' },
        },
      },
    },
    dataFlow: { type: 'string', description: 'How data moves through this subsystem, key methods, async patterns' },
    issues: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['severity', 'file', 'description', 'relevance'],
        properties: {
          severity: { type: 'string', description: 'high|medium|low' },
          file: { type: 'string' },
          description: { type: 'string', description: 'bug, smell, or limitation with file:line if possible' },
          relevance: { type: 'string', description: 'which user concern A/B/C this relates to, or "general"' },
        },
      },
    },
    integrationPoints: { type: 'string', description: 'where AI/providers could plug in, persistence layer, shared services' },
  },
}

const GROUPS = [
  {
    name: 'Photo OCR pipeline',
    files: [
      'Services/PhotoTextRecognitionService.swift',
      'Views/PhotoTranslateView.swift',
      'Views/Components/CameraScannerView.swift',
      'Services/ScreenshotStitchingService.swift',
      'Views/Components/TranslatedScreenshotOverlayView.swift',
      'Models/ScreenshotTranslationStore.swift',
    ],
    focus: 'CRITICAL for concern A and C. Detail every Vision/VNRecognizeTextRequest config: recognitionLevel, recognitionLanguages, usesLanguageCorrection, automaticallyDetectsLanguage, revision. Detail how language is detected and how the photo result is rendered. Note exactly where AI cleanup could be inserted.',
  },
  {
    name: 'Language analysis & detection',
    files: [
      'Services/ChineseTextAnalyzer.swift',
      'Services/EnglishTextAnalyzer.swift',
      'Services/PinyinConverter.swift',
      'Models/TranslationDirection.swift',
      'Views/Components/RubyTextView.swift',
      'Views/Components/EnglishRubyTextView.swift',
    ],
    focus: 'CRITICAL for concern A. Detail every NLLanguageRecognizer / NLTagger usage, any CJK detection heuristics, and how detected language routes processing. Flag any place that hardcodes English or fails to handle Chinese.',
  },
  {
    name: 'AI services & model settings',
    files: [
      'Models/AIModelSettings.swift',
      'Services/OllamaService.swift',
      'Services/AIWordExplanationService.swift',
      'Views/Components/AIWordExplanationView.swift',
      'Services/WordTranslationService.swift',
    ],
    focus: 'CRITICAL for concern B and C. Document the current AI abstraction in full: how Ollama requests are built, how models are listed/selected, how API base URL and keys are stored, what the settings model exposes, and what the provider abstraction (if any) looks like. This is the seam where new providers (OpenAI/Claude/Deepseek/Doubao/Qwen/Kimi/Zhipu/Minimax) must plug in.',
  },
  {
    name: 'Translation core & history',
    files: [
      'Views/TranslateView.swift',
      'Models/TranslationHistory.swift',
      'Models/TranslationState.swift',
      'Views/HistoryTabView.swift',
      'Services/ClipboardService.swift',
      'Services/SpeechService.swift',
    ],
    focus: 'How Apple Translation framework is used, translation direction handling, history persistence.',
  },
  {
    name: 'Speech recognition',
    files: [
      'Services/SpeechRecognitionService.swift',
      'Views/Components/LiveSpeechTranslationView.swift',
    ],
    focus: 'SpeechAnalyzer usage and language handling (relevant to how language is selected elsewhere).',
  },
  {
    name: 'Vocabulary, learning & stats',
    files: [
      'Models/SavedTerm.swift',
      'Views/VocabularyView.swift',
      'Services/VocabularyImportExportService.swift',
      'Models/LearningCard.swift',
      'Models/LearningActivity.swift',
      'Models/GrammarPoint.swift',
      'Views/LearnView.swift',
      'Views/StatsView.swift',
      'Views/PhrasesView.swift',
    ],
    focus: 'Persistence patterns and stores; note how AI explanations could enrich vocabulary.',
  },
  {
    name: 'Settings, More & app shell',
    files: [
      'Views/MacOSSettingsView.swift',
      'Views/MoreView.swift',
      'SwiftMandarinApp.swift',
      'ContentView.swift',
      'Models/AppRouteStore.swift',
      'Item.swift',
    ],
    focus: 'CRITICAL for concern B and C. Document the Settings UI structure (where provider/model pickers and the photo-AI toggle would be added), how stores are injected into the environment, and the tab/navigation shell.',
  },
  {
    name: 'App Intents / Shortcuts',
    files: [
      'Intents/SwiftMandarinShortcutsProvider.swift',
      'Intents/ShortcutEntities.swift',
      'Intents/ShortcutEnums.swift',
      'Intents/ShortcutHelpers.swift',
      'Intents/TranslateTextIntent.swift',
      'Intents/TranslateClipboardIntent.swift',
      'Intents/TranslateScreenshotsIntent.swift',
      'Intents/SpeakTranslationIntent.swift',
      'Intents/LookupVocabularyIntent.swift',
      'Intents/SaveVocabularyTermIntent.swift',
      'Intents/GetRandomPhraseIntent.swift',
      'Intents/GetLearningStatsIntent.swift',
      'Intents/StartReviewIntent.swift',
      'Intents/OpenCameraScannerIntent.swift',
    ],
    focus: 'How shortcuts reuse services; note which services they depend on so refactors stay compatible.',
  },
]

phase('Read')
const maps = await parallel(GROUPS.map(g => () =>
  agent(
    `You are reading a subsystem of the SwiftMandarin macOS/iOS app to build a precise architecture map.\n\n${USER_REQUEST}\n\nSubsystem: "${g.name}". Read these files IN FULL (they are under ${ROOT}/):\n${g.files.map(f => '- ' + f).join('\n')}\n\nSpecial focus: ${g.focus}\n\nRead every file completely with the Read tool. Quote exact API configuration lines where relevant (e.g. recognitionLanguages, recognitionLevel, request bodies, model lists). Return a thorough structured map. In "issues", be specific and tie each to concern A, B, C, or general, with file:line where you can.`,
    { label: `read:${g.name}`, phase: 'Read', schema: SCHEMA }
  )
)).then(rs => rs.filter(Boolean))

phase('Synthesize')
const synthesis = await agent(
  `You are the lead architect synthesizing subsystem maps of the SwiftMandarin app into one actionable brief for an engineer about to implement three changes.\n\n${USER_REQUEST}\n\nHere are the subsystem maps as JSON:\n${JSON.stringify(maps, null, 2)}\n\nProduce a synthesis that gives: (1) a concise overall architecture description; (2) for CONCERN A (photo gibberish + stuck on English, can't read Chinese): the precise root-cause hypothesis and the exact files/lines/APIs to change; (3) for CONCERN B (multi-provider AI with API-fetched model lists): the current AI abstraction and a concrete plan for a provider protocol + per-provider implementations + model-list fetching + settings UI + secure key storage; (4) for CONCERN C (photo AI cleanup toggle): the exact integration seam and data flow; (5) a prioritized, ordered implementation plan with risk notes. Be concrete and reference real type/file names from the maps.`,
  { label: 'synthesize', phase: 'Synthesize' }
)

return { synthesis, subsystemCount: maps.length, maps }

