//
//  AIModelSettings.swift
//  SwiftMandarin
//
//  Manages AI provider settings and preferences for using either
//  Apple Intelligence (Foundation Models) or local Ollama models.
//

import Foundation
import SwiftUI

// MARK: - AI Provider

/// The AI provider to use for AI-powered features
enum AIProvider: String, CaseIterable, Identifiable, Codable {
    case appleIntelligence = "apple"
    case ollama = "ollama"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .appleIntelligence:
            return "Apple Intelligence"
        case .ollama:
            return "Ollama (Local)"
        }
    }

    var description: String {
        switch self {
        case .appleIntelligence:
            return "On-device AI powered by Apple's Foundation Models"
        case .ollama:
            return "Local AI models running via Ollama server"
        }
    }

    var iconName: String {
        switch self {
        case .appleIntelligence:
            return "apple.logo"
        case .ollama:
            return "server.rack"
        }
    }
}

// MARK: - AI Model Settings

/// Observable settings for AI model configuration
@Observable
@MainActor
final class AIModelSettings {

    static let shared = AIModelSettings()

    // MARK: - UserDefaults Keys

    private enum Keys {
        static let provider = "ai_provider"
        static let ollamaModel = "ollama_model"
        static let ollamaHost = "ollama_host"
        static let enableThinking = "ollama_enable_thinking"
        static let contextLength = "ollama_context_length"
    }

    // MARK: - Properties

    /// The currently selected AI provider
    var provider: AIProvider {
        didSet {
            UserDefaults.standard.set(provider.rawValue, forKey: Keys.provider)
        }
    }

    /// The selected Ollama model name
    var ollamaModel: String {
        didSet {
            UserDefaults.standard.set(ollamaModel, forKey: Keys.ollamaModel)
        }
    }

    /// The Ollama server host URL
    var ollamaHost: String {
        didSet {
            UserDefaults.standard.set(ollamaHost, forKey: Keys.ollamaHost)
            updateOllamaServiceHost()
        }
    }

    /// Whether to enable thinking/reasoning mode for Ollama models
    var enableThinking: Bool {
        didSet {
            UserDefaults.standard.set(enableThinking, forKey: Keys.enableThinking)
        }
    }

    /// Context length for Ollama models (in tokens)
    var contextLength: Int {
        didSet {
            UserDefaults.standard.set(contextLength, forKey: Keys.contextLength)
        }
    }

    // MARK: - Computed Properties

    /// Whether Ollama is selected and available
    var isOllamaActive: Bool {
        provider == .ollama && OllamaService.shared.isConnected
    }

    /// Whether Apple Intelligence is available
    var isAppleIntelligenceAvailable: Bool {
        #if canImport(FoundationModels)
        return AIWordExplanationService.shared.isAvailable
        #else
        return false
        #endif
    }

    /// Current effective provider (falls back to available option)
    var effectiveProvider: AIProvider {
        switch provider {
        case .appleIntelligence:
            return isAppleIntelligenceAvailable ? .appleIntelligence : (OllamaService.shared.isConnected ? .ollama : .appleIntelligence)
        case .ollama:
            return OllamaService.shared.isConnected ? .ollama : (isAppleIntelligenceAvailable ? .appleIntelligence : .ollama)
        }
    }

    /// Status message for the current configuration
    var statusMessage: String {
        switch provider {
        case .appleIntelligence:
            if isAppleIntelligenceAvailable {
                return "Apple Intelligence is ready"
            } else {
                return AIWordExplanationService.shared.unavailabilityReason ?? "Apple Intelligence is not available"
            }
        case .ollama:
            if OllamaService.shared.isConnected {
                if ollamaModel.isEmpty {
                    return "Connected - Select a model"
                } else {
                    return "Connected to \(ollamaModel)"
                }
            } else {
                return OllamaService.shared.connectionError ?? "Not connected to Ollama"
            }
        }
    }

    /// Options dictionary for Ollama requests based on current settings
    var ollamaOptions: [String: Ollama.Value] {
        [
            "num_ctx": .int(contextLength),
            "temperature": .double(0.7),
            "top_p": .double(0.9),
            "repeat_penalty": .double(1.1),
            "num_predict": .int(-1),
        ]
    }

    // MARK: - Initialization

    private init() {
        // Load saved settings
        let savedProvider = UserDefaults.standard.string(forKey: Keys.provider) ?? AIProvider.appleIntelligence.rawValue
        self.provider = AIProvider(rawValue: savedProvider) ?? .appleIntelligence

        self.ollamaModel = UserDefaults.standard.string(forKey: Keys.ollamaModel) ?? "gpt-oss:20b"
        self.ollamaHost = UserDefaults.standard.string(forKey: Keys.ollamaHost) ?? "http://localhost:11434"
        self.enableThinking = UserDefaults.standard.object(forKey: Keys.enableThinking) as? Bool ?? true
        self.contextLength = UserDefaults.standard.object(forKey: Keys.contextLength) as? Int ?? 128000

        // Initialize Ollama service host
        updateOllamaServiceHost()
    }

    // MARK: - Methods

    /// Update the Ollama service host URL
    private func updateOllamaServiceHost() {
        if let url = URL(string: ollamaHost) {
            OllamaService.shared.hostURL = url
        }
    }

    /// Refresh connection and available models
    func refreshConnection() async {
        await OllamaService.shared.checkConnection()
        if OllamaService.shared.isConnected {
            await OllamaService.shared.refreshModels()
        }
    }

    /// Select the first available model if none is selected
    func selectDefaultModelIfNeeded() {
        if ollamaModel.isEmpty, let firstModel = OllamaService.shared.availableModels.first {
            ollamaModel = firstModel.name
        }
    }

    /// Reset to default settings
    func resetToDefaults() {
        provider = .appleIntelligence
        ollamaModel = "gpt-oss:20b"
        ollamaHost = "http://localhost:11434"
        enableThinking = true
        contextLength = 128000
    }
}

// MARK: - Ollama Import

import Ollama

//
//  OllamaService.swift
//  SwiftMandarin
//
//  Service for interacting with local Ollama models as an alternative to Apple Intelligence.
//  Provides model discovery, chat completion, and structured output generation.
//

import Foundation
import SwiftUI
import Ollama

// MARK: - Ollama Model Info

/// Represents an available Ollama model with its metadata
struct OllamaModelInfo: Identifiable, Hashable, Codable {
    var id: String { name }
    let name: String
    let size: Int64
    let parameterSize: String
    let family: String
    let supportsThinking: Bool
    let supportsTools: Bool

    /// Human-readable size string
    var sizeString: String {
        let formatter = ByteCountFormatter()
        formatter.countStyle = .file
        return formatter.string(fromByteCount: size)
    }
}

// MARK: - Ollama Service

/// Service that provides access to local Ollama models for AI-powered features
@Observable
@MainActor
final class OllamaService {

    static let shared = OllamaService()

    // MARK: - Properties

    /// The Ollama client instance
    private var client: Ollama.Client

    /// Available models discovered from Ollama
    private(set) var availableModels: [OllamaModelInfo] = []

    /// Whether Ollama server is reachable
    private(set) var isConnected: Bool = false

    /// Last connection error if any
    private(set) var connectionError: String?

    /// Whether we're currently loading models
    private(set) var isLoadingModels: Bool = false

    /// The Ollama server host URL
    var hostURL: URL {
        get { client.host }
        set { 
            client = Ollama.Client(host: newValue)
            // Re-check connection when host changes
            Task { await checkConnection() }
        }
    }

    // MARK: - Configuration

    /// Default options for gpt-oss 20b model with extended context and reasoning
    static let defaultOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),           // 128k context window
        "temperature": .double(0.7),        // Balanced creativity
        "top_p": .double(0.9),              // Nucleus sampling
        "repeat_penalty": .double(1.1),     // Reduce repetition
        "num_predict": .int(-1),            // No limit on tokens
    ]

    /// Options optimized for reasoning tasks
    static let reasoningOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),            // 128k context window
        "temperature": .double(0.3),         // More deterministic for reasoning
        "top_p": .double(0.95),
        "repeat_penalty": .double(1.05),
        "num_predict": .int(-1),
    ]

    // MARK: - Initialization

    private init() {
        // Initialize with default localhost
        self.client = Ollama.Client.default
    }

    // MARK: - Connection Management

    /// Check if Ollama server is reachable
    func checkConnection() async {
        do {
            _ = try await client.version()
            isConnected = true
            connectionError = nil
        } catch {
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    /// Refresh the list of available models from Ollama
    func refreshModels() async {
        isLoadingModels = true
        defer { isLoadingModels = false }

        do {
            let response = try await client.listModels()

            // Get detailed info for each model to check capabilities
            var models: [OllamaModelInfo] = []
            for model in response.models {
                // Try to get capabilities for each model
                var supportsThinking = false
                var supportsTools = false

                do {
                    let details = try await client.showModel(Ollama.Model.ID(rawValue: model.name)!)
                    supportsThinking = details.capabilities.contains(.thinking)
                    supportsTools = details.capabilities.contains(.tools)
                } catch {
                    // Ignore errors fetching details, use defaults
                }

                let info = OllamaModelInfo(
                    name: model.name,
                    size: model.size,
                    parameterSize: model.details.parameterSize,
                    family: model.details.family,
                    supportsThinking: supportsThinking,
                    supportsTools: supportsTools
                )
                models.append(info)
            }

            availableModels = models.sorted { $0.name < $1.name }
            isConnected = true
            connectionError = nil
        } catch {
            availableModels = []
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    // MARK: - Chat Completion

    /// Generate a chat completion with the specified model
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions for the model
    ///   - userPrompt: The user's message
    ///   - enableThinking: Whether to enable thinking/reasoning mode
    ///   - options: Additional model options
    /// - Returns: The model's response content
    func chat(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) async throws -> (content: String, thinking: String?) {
        let modelID = Ollama.Model.ID(rawValue: model)!

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return (content: response.message.content, thinking: response.message.thinking)
    }

    /// Generate a streaming chat completion
    func chatStream(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) throws -> AsyncThrowingStream<Ollama.Client.ChatResponse, Error> {
        let modelID = Ollama.Model.ID(rawValue: model)!

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        return try client.chatStream(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )
    }

    // MARK: - Structured Output Generation

    /// Generate a structured JSON response matching a schema
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions
    ///   - userPrompt: User message
    ///   - schema: JSON schema for the expected output
    ///   - enableThinking: Whether to enable thinking mode
    /// - Returns: The JSON string response
    func generateStructured(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        schema: Ollama.Value,
        enableThinking: Bool = true
    ) async throws -> String {
        let modelID = Ollama.Model.ID(rawValue: model)!

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: Self.reasoningOptions,
            format: schema,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return response.message.content
    }

    /// Generate structured output and decode it to a Codable type
    func generateAndDecode<T: Codable>(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        type: T.Type,
        enableThinking: Bool = true
    ) async throws -> T {
        // Build JSON schema from type (simplified approach)
        let jsonString = try await generateStructured(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            schema: "json",
            enableThinking: enableThinking
        )

        guard let data = jsonString.data(using: .utf8) else {
            throw OllamaServiceError.invalidResponse("Response is not valid UTF-8")
        }

        do {
            return try JSONDecoder().decode(T.self, from: data)
        } catch {
            throw OllamaServiceError.decodingFailed("Failed to decode response: \(error.localizedDescription)")
        }
    }

    // MARK: - Translation

    /// Translate text using Ollama
    /// - Parameters:
    ///   - text: The text to translate
    ///   - sourceIsChinese: Whether the source is Chinese (true) or English (false)
    ///   - model: The model to use
    /// - Returns: The translated text
    func translate(
        _ text: String,
        sourceIsChinese: Bool,
        model: String
    ) async throws -> String {
        let systemPrompt = """
        You are an expert translator specializing in English and Mandarin Chinese (Simplified).

        Your translations should be:
        1. ACCURATE: Preserve the exact meaning and intent of the source text
        2. NATURAL: Use idiomatic expressions appropriate for the target language
        3. CONTEXTUAL: Consider the context and register (formal/informal)
        4. CULTURAL: Adapt cultural references when necessary for clarity

        For English to Chinese translations:
        - Use Simplified Chinese characters (简体中文)
        - Choose vocabulary appropriate for modern standard Mandarin (普通话)
        - Maintain the tone and style of the original

        For Chinese to English translations:
        - Use natural, fluent English
        - Preserve nuances and connotations where possible
        - Clarify ambiguous cultural references if needed

        Respond with ONLY the translation, no explanations or additional text.
        """

        let direction = sourceIsChinese ? "Chinese to English" : "English to Chinese"
        let userPrompt = """
        Translate the following text from \(direction):

        \(text)
        """

        let (content, _) = try await chat(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            enableThinking: false, // Translation doesn't need reasoning
            options: Self.defaultOptions
        )

        return content.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

// MARK: - Errors

enum OllamaServiceError: LocalizedError {
    case notConnected
    case modelNotFound(String)
    case invalidResponse(String)
    case decodingFailed(String)
    case generationFailed(String)

    var errorDescription: String? {
        switch self {
        case .notConnected:
            return "Ollama server is not connected. Please ensure Ollama is running."
        case .modelNotFound(let name):
            return "Model '\(name)' not found. Please pull the model first."
        case .invalidResponse(let detail):
            return "Invalid response from Ollama: \(detail)"
        case .decodingFailed(let detail):
            return "Failed to decode response: \(detail)"
        case .generationFailed(let detail):
            return "Generation failed: \(detail)"
        }
    }
}

