1	//
2	//  PhotoTranslateView.swift
3	//  SwiftMandarin
4	//
5	//  Photo translation view for scanning and translating text
6	//  Supports both English → Chinese and Chinese → English translation
7	//
8	
9	import SwiftUI
10	import PhotosUI
11	import Translation
12	import NaturalLanguage
13	
14	// MARK: - DetectedLanguage Extension for Photo Translation UI
15	
16	extension DetectedLanguage {
17	    /// Display name for UI
18	    var displayName: String {
19	        switch self {
20	        case .english: return "英文"
21	        case .chinese: return "中文"
22	        case .unknown, .other: return "未知"
23	        }
24	    }
25	    
26	    /// Icon for language badge
27	    var icon: String {
28	        switch self {
29	        case .english: return "e.circle.fill"
30	        case .chinese: return "character.textbox"
31	        case .unknown, .other: return "questionmark.circle"
32	        }
33	    }
34	}
35	
36	/// Main view for photo-based translation
37	struct PhotoTranslateView: View {
38	    @Environment(SavedTermsStore.self) private var savedTermsStore
39	    @Environment(AppRouteStore.self) private var routeStore
40	    
41	    // State
42	    @State private var sourceText: String = ""
43	    @State private var cleanedChineseText: String = ""             // Cleaned Chinese text for RubyTextView
44	    @State private var analyzedSentences: [AnalyzedSentence] = []  // For English text
45	    @State private var chineseTranslation: String = ""             // Full Chinese → English translation
46	    @State private var isProcessing: Bool = false
47	    @State private var errorMessage: String?
48	    @State private var detectedLanguage: DetectedLanguage = .unknown
49	    
50	    // Photo picker
51	    @State private var selectedPhoto: PhotosPickerItem?
52	    @State private var selectedImageData: Data?
53	    
54	    // Camera scanner
55	    @State private var showCameraScanner: Bool = false
56	    @State private var capturedText: String = ""
57	    
58	    // Screenshot translation overlay
59	    @State private var showScreenshotTranslation: Bool = false
60	    
61	    // Word detail - English
62	    @State private var selectedEnglishWord: AnalyzedEnglishWord?
63	    // Word detail - Chinese (using RubySegment)
64	    @State private var selectedChineseSegment: RubySegment?
65	    
66	    // Translation
67	    @State private var translationConfiguration: TranslationSession.Configuration?
68	    @State private var isTranslating: Bool = false
69	    
70	    // Settings
71	    @State private var showGrammarPoints: Bool = true
72	    
73	    /// Check if we have any results to display
74	    private var hasResults: Bool {
75	        !analyzedSentences.isEmpty || !cleanedChineseText.isEmpty
76	    }
77	    
78	    var body: some View {
79	        NavigationStack {
80	            ScrollView {
81	                VStack(spacing: 20) {
82	                    // Input section
83	                    inputSection
84	                    
85	                    // Results section - show based on detected language
86	                    if hasResults {
87	                        resultsSection
88	                    } else if isProcessing {
89	                        processingView
90	                    } else if let error = errorMessage {
91	                        errorView(error)
92	                    } else {
93	                        emptyStateView
94	                    }
95	                }
96	                .padding()
97	            }
98	            .navigationTitle("拍照翻译")
99	            #if os(iOS)
100	            .navigationBarTitleDisplayMode(.large)
101	            #endif
102	            .toolbar {
103	                ToolbarItem(placement: .primaryAction) {
104	                    Menu {
105	                        if detectedLanguage == .english {
106	                            Toggle("显示语法知识点", isOn: $showGrammarPoints)
107	                            Divider()
108	                        }
109	                        
110	                        Button(role: .destructive) {
111	                            clearAll()
112	                        } label: {
113	                            Label("清除内容", systemImage: "trash")
114	                        }
115	                        .disabled(sourceText.isEmpty && !hasResults)
116	                    } label: {
117	                        Image(systemName: "ellipsis.circle")
118	                    }
119	                }
120	            }
121	            .sheet(isPresented: $showCameraScanner) {
122	                CameraScannerSheet(capturedText: $capturedText)
123	            }
124	            .sheet(item: $selectedEnglishWord) { word in
125	                EnglishWordDetailSheet(word: word)
126	            }
127	            .sheet(item: $selectedChineseSegment) { segment in
128	                WordDetailPopover(
129	                    segment: segment,
130	                    contextTranslation: chineseTranslation,
131	                    onSave: { definition in
132	                        saveChineseWord(segment, definition: definition)
133	                    },
134	                    onCopy: { },
135	                    onDismiss: { selectedChineseSegment = nil }
136	                )
137	            }
138	            .sheet(isPresented: $showScreenshotTranslation) {
139	                TranslatedScreenshotOverlayView()
140	                    .environment(ScreenshotTranslationStore.shared)
141	            }
142	            .task(id: routeStore.pendingAction?.id) {
143	                applyPendingRouteAction()
144	            }
145	            .onChange(of: capturedText) { _, newValue in
146	                if !newValue.isEmpty {
147	                    sourceText = newValue
148	                    Task {
149	                        await processText(newValue)
150	                    }
151	                }
152	            }
153	            .onChange(of: selectedPhoto) { _, newValue in
154	                Task {
155	                    await loadAndProcessImage(newValue)
156	                }
157	            }
158	            .translationTask(translationConfiguration) { session in
159	                await translateSentences(session: session)
160	            }
161	        }
162	    }
163	    
164	    // MARK: - Input Section
165	    
166	    private var inputSection: some View {
167	        VStack(spacing: 16) {
168	            // Input buttons
169	            HStack(spacing: 12) {
170	                #if os(iOS)
171	                // Camera button - only show if device supports scanning
172	                if CameraScannerView.isSupported {
173	                    Button {
174	                        showCameraScanner = true
175	                    } label: {
176	                        Label("相机扫描", systemImage: "camera.fill")
177	                            .frame(maxWidth: .infinity)
178	                    }
179	                    .buttonStyle(.borderedProminent)
180	                    .controlSize(.large)
181	                    .disabled(!CameraScannerView.isAvailable)
182	                }
183	                #endif
184	                
185	                // Photo picker
186	                PhotosPicker(selection: $selectedPhoto, matching: .images) {
187	                    Label("选择图片", systemImage: "photo.fill")
188	                        .frame(maxWidth: .infinity)
189	                }
190	                .buttonStyle(.bordered)
191	                .controlSize(.large)
192	            }
193	            
194	            // Text input
195	            VStack(alignment: .leading, spacing: 8) {
196	                HStack {
197	                    Text("输入中文或英文文本")
198	                        .font(.caption)
199	                        .foregroundStyle(.secondary)
200	                    
201	                    Spacer()
202	                    
203	                    // Show detected language
204	                    if detectedLanguage != .unknown {
205	                        Label(detectedLanguage.displayName, systemImage: detectedLanguage.icon)
206	                            .font(.caption)
207	                            .foregroundStyle(detectedLanguage == .english ? .blue : .orange)
208	                            .padding(.horizontal, 8)
209	                            .padding(.vertical, 2)
210	                            .background(
211	                                Capsule()
212	                                    .fill(detectedLanguage == .english ? Color.blue.opacity(0.1) : Color.orange.opacity(0.1))
213	                            )
214	                    }
215	                }
216	                
217	                TextEditor(text: $sourceText)
218	                    .font(.body)
219	                    .frame(minHeight: 100)
220	                    .scrollContentBackground(.hidden)
221	                    .padding(12)
222	                    .background(
223	                        RoundedRectangle(cornerRadius: 12)
224	                            .fill(.ultraThinMaterial)
225	                    )
226	                    .overlay(alignment: .topLeading) {
227	                        if sourceText.isEmpty {
228	                            Text("输入或粘贴文字内容（支持中英文）...")
229	                                .font(.body)
230	                                .foregroundStyle(.tertiary)
231	                                .padding(.horizontal, 16)
232	                                .padding(.top, 20)
233	                                .allowsHitTesting(false)
234	                        }
235	                    }
236	                
237	                HStack {
238	                    Button {
239	                        if let pastedText = ClipboardService.paste(), !pastedText.isEmpty {
240	                            sourceText = pastedText
241	                        }
242	                    } label: {
243	                        Label("粘贴", systemImage: "doc.on.clipboard")
244	                    }
245	                    .buttonStyle(.bordered)
246	                    .controlSize(.small)
247	                    
248	                    Spacer()
249	                    
250	                    if !sourceText.isEmpty {
251	                        Text("\(sourceText.count) 字符")
252	                            .font(.caption)
253	                            .foregroundStyle(.secondary)
254	                    }
255	                    
256	                    Button {
257	                        Task {
258	                            await processText(sourceText)
259	                        }
260	                    } label: {
261	                        Label("分析翻译", systemImage: "wand.and.stars")
262	                    }
263	                    .buttonStyle(.borderedProminent)
264	                    .controlSize(.small)
265	                    .disabled(sourceText.isEmpty || isProcessing)
266	                }
267	            }
268	        }
269	        .padding()
270	        .background(
271	            RoundedRectangle(cornerRadius: 16)
272	                .fill(.background)
273	                .shadow(color: .black.opacity(0.05), radius: 8, y: 4)
274	        )
275	    }
276	    
277	    // MARK: - Results Section
278	    
279	    private var resultsSection: some View {
280	        VStack(spacing: 16) {
281	            // Show different results based on detected language
282	            if detectedLanguage == .english {
283	                englishResultsSection
284	            } else if detectedLanguage == .chinese {
285	                chineseResultsSection
286	            }
287	        }
288	    }
289	    
290	    /// Results section for English text (English → Chinese)
291	    private var englishResultsSection: some View {
292	        VStack(spacing: 16) {
293	            // Summary
294	            HStack {
295	                VStack(alignment: .leading) {
296	                    HStack {
297	                        Text("分析结果")
298	                            .font(.headline)
299	                        Label("英文→中文", systemImage: "arrow.right")
300	                            .font(.caption)
301	                            .foregroundStyle(.blue)
302	                    }
303	                    Text("\(analyzedSentences.count) 个句子, \(totalEnglishWordCount) 个单词")
304	                        .font(.caption)
305	                        .foregroundStyle(.secondary)
306	                }
307	                
308	                Spacer()
309	                
310	                Button {
311	                    triggerTranslation()
312	                } label: {
313	                    Label(isTranslating ? "翻译中..." : "翻译全部", systemImage: "translate")
314	                }
315	                .buttonStyle(.borderedProminent)
316	                .disabled(isTranslating)
317	            }
318	            
319	            // Sentences
320	            ForEach(Array(analyzedSentences.enumerated()), id: \.element.id) { index, sentence in
321	                SentenceCard(
322	                    sentence: sentence,
323	                    showGrammarPoints: showGrammarPoints,
324	                    onWordTap: { word in
325	                        selectedEnglishWord = word
326	                    }
327	                )
328	            }
329	            
330	            // Save all words button
331	            Button {
332	                saveAllEnglishWordsToVocabulary()
333	            } label: {
334	                Label("保存所有单词到词汇本", systemImage: "bookmark")
335	                    .frame(maxWidth: .infinity)
336	            }
337	            .buttonStyle(.bordered)
338	        }
339	    }
340	    
341	    /// Results section for Chinese text (Chinese → English)
342	    private var chineseResultsSection: some View {
343	        VStack(spacing: 16) {
344	            // Summary
345	            HStack {
346	                VStack(alignment: .leading) {
347	                    HStack {
348	                        Text("分析结果")
349	                            .font(.headline)
350	                        Label("中文→英文", systemImage: "arrow.right")
351	                            .font(.caption)
352	                            .foregroundStyle(.orange)
353	                    }
354	                    Text("\(cleanedChineseText.count) 个字符")
355	                        .font(.caption)
356	                        .foregroundStyle(.secondary)
357	                }
358	                
359	                Spacer()
360	                
361	                Button {
362	                    triggerChineseTranslation()
363	                } label: {
364	                    Label(isTranslating ? "翻译中..." : "翻译全部", systemImage: "translate")
365	                }
366	                .buttonStyle(.borderedProminent)
367	                .disabled(isTranslating)
368	            }
369	            
370	            // Full translation card
371	            if !chineseTranslation.isEmpty {
372	                VStack(alignment: .leading, spacing: 12) {
373	                    Text("英文翻译")
374	                        .font(.caption)
375	                        .foregroundStyle(.secondary)
376	                    
377	                    Text(chineseTranslation)
378	                        .font(.title3)
379	                        .fontWeight(.medium)
380	                    
381	                    Button {
382	                        SpeechService.speakEnglish(chineseTranslation)
383	                    } label: {
384	                        Label("朗读英文", systemImage: "speaker.wave.2")
385	                    }
386	                    .buttonStyle(.bordered)
387	                    .controlSize(.small)
388	                }
389	                .frame(maxWidth: .infinity, alignment: .leading)
390	                .padding()
391	                .background(
392	                    RoundedRectangle(cornerRadius: 12)
393	                        .fill(.ultraThinMaterial)
394	                )
395	            }
396	            
397	            // Word-by-word analysis using existing RubyTextView
398	            VStack(alignment: .leading, spacing: 12) {
399	                Text("逐词分析")
400	                    .font(.caption)
401	                    .foregroundStyle(.secondary)
402	                
403	                RubyTextView(
404	                    chineseText: cleanedChineseText,
405	                    englishMeaning: chineseTranslation,
406	                    onWordTap: { segment in
407	                        selectedChineseSegment = segment
408	                    }
409	                )
410	            }
411	            .padding()
412	            .background(
413	                RoundedRectangle(cornerRadius: 16)
414	                    .fill(.background)
415	                    .shadow(color: .black.opacity(0.05), radius: 8, y: 4)
416	            )
417	            
418	            // Save all words button
419	            Button {
420	                Task {
421	                    await saveAllChineseWordsToVocabulary()
422	                }
423	            } label: {
424	                Label("保存所有词汇到词汇本", systemImage: "bookmark")
425	                    .frame(maxWidth: .infinity)
426	            }
427	            .buttonStyle(.bordered)
428	        }
429	    }
