431	    // MARK: - Helper Views
432	    
433	    private var processingView: some View {
434	        VStack(spacing: 16) {
435	            ProgressView()
436	                .controlSize(.large)
437	            Text("正在处理...")
438	                .font(.headline)
439	                .foregroundStyle(.secondary)
