447	            Label("处理失败", systemImage: "exclamationmark.triangle")
448	        } description: {
449	            Text(error)
450	        } actions: {
451	            Button("重试") {
452	                Task {
453	                    await processText(sourceText)
454	                }
455	            }
456	            .buttonStyle(.borderedProminent)
457	        }
458	    }
459	    
460	    private var emptyStateView: some View {
461	        ContentUnavailableView {
462	            Label("拍照翻译", systemImage: "camera.viewfinder")
463	        } description: {
464	            Text("拍摄或选择图片，自动识别文字并翻译\n支持中文↔英文双向翻译")
465	        }
466	        .padding(.vertical, 40)
467	    }
468	    
469	    // MARK: - Computed Properties
470	    
471	    private var totalEnglishWordCount: Int {
472	        analyzedSentences.reduce(0) { $0 + $1.words.count }
473	    }
474	
475	    private func containsChinese(_ text: String) -> Bool {
476	        text.contains { $0.isChineseCharacter }
477	    }
478	
479	    private func applyPendingRouteAction() {
480	        guard let action = routeStore.pendingAction else { return }
481	        switch action.kind {
482	        case .openCameraScanner:
483	            #if os(iOS)
484	            showCameraScanner = true
485	            #endif
486	        case .translateScreenshots:
487	            showScreenshotTranslation = true
488	        default:
489	            break
490	        }
491	        routeStore.clearPendingAction()
492	    }
493	    
494	    // MARK: - Actions
495	    
496	    private func loadAndProcessImage(_ item: PhotosPickerItem?) async {
497	        guard let item = item else { return }
498	        
499	        isProcessing = true
500	        errorMessage = nil
501	        
502	        do {
503	            guard let data = try await item.loadTransferable(type: Data.self) else {
504	                throw RecognitionError.invalidImage
505	            }
506	            
507	            selectedImageData = data
508	            let result = try await PhotoTextRecognitionService.shared.recognizeText(from: data)
509	            
510	            await MainActor.run {
511	                // Show cleaned text (with line breaks removed) for better readability
512	                sourceText = result.cleanedText
513	            }
514	            
515	            // Process the cleaned text for proper sentence detection
516	            await processText(result.cleanedText)
517	            
518	        } catch {
519	            await MainActor.run {
520	                errorMessage = error.localizedDescription
521	                isProcessing = false
522	            }
523	        }
524	    }
525	    
526	    private func processText(_ text: String) async {
527	        guard !text.isEmpty else { return }
528	        
529	        await MainActor.run {
530	            isProcessing = true
531	            errorMessage = nil
532	            // Clear previous results
533	            analyzedSentences = []
534	            cleanedChineseText = ""
535	            chineseTranslation = ""
536	        }
537	        
538	        // Clean the text first to handle any line breaks from manual input
539	        let cleanedText = cleanTextForProcessing(text)
540	        
541	        // Detect language
542	        let language = detectLanguage(cleanedText)
543	        
544	        await MainActor.run {
545	            detectedLanguage = language
546	        }
547	        
548	        if language == .english {
549	            // English text - analyze sentences and words
550	            let sentences = EnglishTextAnalyzer.shared.analyzeSentences(cleanedText)
551	            await MainActor.run {
552	                analyzedSentences = sentences
553	                isProcessing = false
554	            }
555	        } else if language == .chinese {
556	            // Chinese text - store cleaned text for RubyTextView to analyze
557	            await MainActor.run {
558	                cleanedChineseText = cleanedText
559	                isProcessing = false
560	            }
561	        } else {
562	            // Unknown language - try English first
563	            let sentences = EnglishTextAnalyzer.shared.analyzeSentences(cleanedText)
564	            await MainActor.run {
565	                analyzedSentences = sentences
566	                detectedLanguage = .english
567	                isProcessing = false
568	            }
569	        }
570	    }
571	    
572	    /// Detect the primary language of the text
573	    private func detectLanguage(_ text: String) -> DetectedLanguage {
574	        let recognizer = NLLanguageRecognizer()
575	        recognizer.processString(text)
576	        
577	        guard let dominantLanguage = recognizer.dominantLanguage else {
578	            return .unknown
579	        }
580	        
581	        switch dominantLanguage {
582	        case .english:
583	            return .english
584	        case .simplifiedChinese, .traditionalChinese:
585	            return .chinese
586	        default:
587	            // Check if it contains significant Chinese characters
588	            let chineseCharCount = text.unicodeScalars.filter { 
589	                (0x4E00...0x9FFF).contains($0.value) || // CJK Unified Ideographs
590	                (0x3400...0x4DBF).contains($0.value)    // CJK Extension A
591	            }.count
592	            
593	            if chineseCharCount > text.count / 3 {
594	                return .chinese
595	            }
596	            return .english
597	        }
598	    }
599	    
600	    /// Clean text for processing - removes line breaks that split sentences
601	    private func cleanTextForProcessing(_ text: String) -> String {
602	        var result = text
603	        
604	        // Replace multiple whitespace/newlines with single space
605	        result = result.components(separatedBy: .whitespacesAndNewlines)
606	            .filter { !$0.isEmpty }
607	            .joined(separator: " ")
608	        
609	        // Fix hyphenated words split across lines
610	        result = result.replacingOccurrences(of: "- ", with: "")
611	        
612	        // Ensure proper spacing after punctuation
613	        result = result.replacingOccurrences(of: "\\.([A-Z])", with: ". $1", options: .regularExpression)
614	        result = result.replacingOccurrences(of: "\\?([A-Z])", with: "? $1", options: .regularExpression)
615	        result = result.replacingOccurrences(of: "!([A-Z])", with: "! $1", options: .regularExpression)
616	        
617	        // Clean up multiple spaces
618	        result = result.replacingOccurrences(of: "  +", with: " ", options: .regularExpression)
619	        
620	        return result.trimmingCharacters(in: .whitespacesAndNewlines)
621	    }
622	    
623	    /// Trigger English → Chinese translation
624	    private func triggerTranslation() {
625	        guard !analyzedSentences.isEmpty else { return }
626	        
627	        if translationConfiguration == nil {
628	            translationConfiguration = TranslationSession.Configuration(
629	                source: Locale.Language(identifier: "en"),
630	                target: Locale.Language(identifier: "zh-Hans")
631	            )
632	        } else {
633	            translationConfiguration?.invalidate()
634	        }
635	    }
636	    
637	    /// Trigger Chinese → English translation
638	    private func triggerChineseTranslation() {
639	        guard !cleanedChineseText.isEmpty else { return }
640	        
641	        Task {
642	            await MainActor.run {
643	                isTranslating = true
644	            }
645	            
646	            do {
647	                // Translate the full text from Chinese to English
648	                let translation = try await WordTranslationService.shared.translateToEnglish(cleanedChineseText)
649	                
650	                await MainActor.run {
651	                    chineseTranslation = translation
652	                }
653	            } catch {
654	                await MainActor.run {
655	                    errorMessage = "翻译失败: \(error.localizedDescription)"
656	                }
657	            }
658	            
659	            await MainActor.run {
660	                isTranslating = false
661	            }
662	        }
663	    }
664	    
665	    private func translateSentences(session: TranslationSession) async {
666	        await MainActor.run {
667	            isTranslating = true
668	        }
669	        
670	        do {
671	            // Capture a snapshot of sentences to translate
672	            let sentenceCount = await MainActor.run { analyzedSentences.count }
673	            
674	            // Translate each sentence
675	            for i in 0..<sentenceCount {
676	                // Safely get the sentence text
677	                let sentenceText = await MainActor.run { 
678	                    i < analyzedSentences.count ? analyzedSentences[i].text : nil 
679	                }
680	                guard let text = sentenceText else { continue }
681	                
682	                let response = try await session.translate(text)
683	                await MainActor.run {
684	                    if i < analyzedSentences.count {
685	                        analyzedSentences[i].translation = response.targetText
686	                    }
687	                }
688	            }
689	            
690	            // Translate individual words - collect all words first
691	            var wordTranslations: [(sentenceIndex: Int, wordIndex: Int, translation: String)] = []
692	            
693	            for i in 0..<sentenceCount {
694	                let wordCount = await MainActor.run { 
695	                    i < analyzedSentences.count ? analyzedSentences[i].words.count : 0 
696	                }
697	                
698	                for j in 0..<wordCount {
699	                    // Safely get word info
700	                    let wordInfo = await MainActor.run { () -> (lemma: String, partOfSpeech: EnglishPartOfSpeech)? in
701	                        guard i < analyzedSentences.count, j < analyzedSentences[i].words.count else { return nil }
702	                        let word = analyzedSentences[i].words[j]
703	                        return (word.lemma, word.partOfSpeech)
704	                    }
705	                    
706	                    guard let info = wordInfo else { continue }
707	                    
708	                    // Skip common words like "the", "a", "is"
709	                    if info.partOfSpeech != .determiner && info.partOfSpeech != .particle {
710	                        let response = try await session.translate(info.lemma)
711	                        wordTranslations.append((i, j, response.targetText))
712	                    }
713	                }
714	            }
715	            
716	            // Apply all word translations at once on main actor
717	            await MainActor.run {
718	                for (sentenceIndex, wordIndex, translation) in wordTranslations {
719	                    if sentenceIndex < analyzedSentences.count,
720	                       wordIndex < analyzedSentences[sentenceIndex].words.count {
721	                        analyzedSentences[sentenceIndex].words[wordIndex].translation = translation
722	                    }
723	                }
724	            }
725	        } catch {
726	            await MainActor.run {
727	                errorMessage = "翻译失败: \(error.localizedDescription)"
728	            }
729	        }
730	        
731	        await MainActor.run {
732	            isTranslating = false
733	        }
734	    }
735	    
736	    /// Save all English words from the analysis to vocabulary
737	    private func saveAllEnglishWordsToVocabulary() {
738	        for sentence in analyzedSentences {
739	            for word in sentence.words {
740	                // Skip common function words
741	                guard word.partOfSpeech != .determiner,
742	                      word.partOfSpeech != .particle,
743	                      word.partOfSpeech != .conjunction else { continue }
744	
745	                let chinese = (word.translation ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
746	                guard !chinese.isEmpty, containsChinese(chinese) else { continue }
747	                
748	                let term = SavedTerm(
749	                    chinese: chinese,
750	                    pinyin: PinyinConverter.convert(chinese),
751	                    definition: word.lemma.caseInsensitiveCompare(word.text) == .orderedSame ? word.text : "\(word.text) (\(word.lemma))",
752	                    partOfSpeech: word.partOfSpeech.englishName
753	                )
754	                
755	                if !savedTermsStore.contains(chinese: term.chinese) {
756	                    savedTermsStore.add(term)
757	                }
758	            }
759	        }
760	    }
761	    
762	    /// Save all Chinese words from the analysis to vocabulary
763	    private func saveAllChineseWordsToVocabulary() async {
764	        let analyzedWords = ChineseTextAnalyzer.shared.segmentWithPartsOfSpeech(cleanedChineseText)
765	        let meaningfulWords = analyzedWords.filter { word in
766	            let trimmed = word.text.trimmingCharacters(in: .whitespacesAndNewlines)
767	            guard !trimmed.isEmpty else { return false }
768	            guard trimmed.contains(where: { $0.isChineseCharacter }) else { return false }
769	            return !savedTermsStore.contains(chinese: trimmed)
770	        }
771	
772	        guard !meaningfulWords.isEmpty else { return }
773	
774	        do {
775	            let uniqueWordTexts = meaningfulWords.reduce(into: [String]()) { result, word in
776	                if !result.contains(word.text) {
777	                    result.append(word.text)
778	                }
779	            }
780	
781	            let translations = try await WordTranslationService.shared.translateBatch(uniqueWordTexts, sourceIsChinese: true)
782	
783	            for word in meaningfulWords {
784	                let definition = translations[word.text]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
785	                guard !definition.isEmpty else { continue }
786	
787	                let term = SavedTerm(
788	                    chinese: word.text,
789	                    pinyin: PinyinConverter.convert(word.text),
790	                    definition: definition,
791	                    partOfSpeech: word.partOfSpeech.displayName
792	                )
793	
794	                if !savedTermsStore.contains(chinese: term.chinese) {
795	                    savedTermsStore.add(term)
796	                }
797	            }
798	        } catch {
799	            errorMessage = "逐词保存失败: \(error.localizedDescription)"
800	        }
801	    }
802	    
803	    /// Save a single Chinese word to vocabulary
804	    private func saveChineseWord(_ segment: RubySegment, definition: String) {
805	        let term = SavedTerm(
806	            chinese: segment.text,
807	            pinyin: segment.pinyin,
808	            definition: definition,
809	            partOfSpeech: segment.partOfSpeech.displayName
810	        )
811	        
812	        if !savedTermsStore.contains(chinese: term.chinese) {
813	            savedTermsStore.add(term)
814	        }
815	    }
816	    
817	    private func clearAll() {
818	        sourceText = ""
819	        analyzedSentences = []
820	        cleanedChineseText = ""
821	        chineseTranslation = ""
822	        detectedLanguage = .unknown
823	        capturedText = ""
824	        selectedPhoto = nil
825	        selectedImageData = nil
826	        selectedEnglishWord = nil
827	        selectedChineseSegment = nil
828	        errorMessage = nil
829	        isProcessing = false
830	        isTranslating = false
831	        translationConfiguration = nil
832	    }
833	}
