52	    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {
53	        // Only control scanning if we have a DataScannerViewController
54	        guard let scanner = uiViewController as? DataScannerViewController else { return }
55	        
56	        if isScanning {
57	            if !scanner.isScanning {
58	                try? scanner.startScanning()
59	            }
60	        } else {
61	            if scanner.isScanning {
62	                scanner.stopScanning()
63	            }
64	        }
65	    }
66	    
67	    func makeCoordinator() -> Coordinator {
68	        Coordinator(self)
69	    }
70	    
71	    class Coordinator: NSObject, DataScannerViewControllerDelegate {
72	        let parent: CameraScannerView
73	        private var lastRecognizedText: String = ""
74	        
75	        init(_ parent: CameraScannerView) {
76	            self.parent = parent
77	        }
78	        
79	        func dataScanner(_ dataScanner: DataScannerViewController, didTapOn item: RecognizedItem) {
80	            switch item {
81	            case .text(let text):
82	                let cleanedText = cleanTextForSentences(text.transcript)
83	                parent.recognizedText = cleanedText
84	                parent.onTextRecognized(cleanedText)
85	            default:
86	                break
87	            }
88	        }
89	        
90	        func dataScanner(_ dataScanner: DataScannerViewController, didAdd addedItems: [RecognizedItem], allItems: [RecognizedItem]) {
91	            // Combine all recognized text and clean it
92	            let rawText = allItems.compactMap { item -> String? in
93	                if case .text(let text) = item {
94	                    return text.transcript
95	                }
96	                return nil
97	            }.joined(separator: " ")
98	            
99	            let cleanedText = cleanTextForSentences(rawText)
100	            
101	            // Only update if text changed significantly
102	            if cleanedText != lastRecognizedText {
103	                lastRecognizedText = cleanedText
104	                parent.recognizedText = cleanedText
105	            }
106	        }
107	        
108	        func dataScanner(_ dataScanner: DataScannerViewController, didRemove removedItems: [RecognizedItem], allItems: [RecognizedItem]) {
109	            // Update text when items are removed
110	            let rawText = allItems.compactMap { item -> String? in
111	                if case .text(let text) = item {
112	                    return text.transcript
113	                }
114	                return nil
115	            }.joined(separator: " ")
116	            
117	            let cleanedText = cleanTextForSentences(rawText)
118	            lastRecognizedText = cleanedText
119	            parent.recognizedText = cleanedText
120	        }
121	        
122	        /// Clean OCR text to properly join sentences split by line breaks
123	        private func cleanTextForSentences(_ text: String) -> String {
124	            var result = text
125	            
126	            // Replace multiple whitespace/newlines with single space
127	            result = result.components(separatedBy: .whitespacesAndNewlines)
128	                .filter { !$0.isEmpty }
129	                .joined(separator: " ")
130	            
131	            // Fix hyphenated words split across lines
132	            result = result.replacingOccurrences(of: "- ", with: "")
133	            
134	            // Ensure proper spacing after punctuation
135	            result = result.replacingOccurrences(of: "\\.([A-Z])", with: ". $1", options: .regularExpression)
136	            result = result.replacingOccurrences(of: "\\?([A-Z])", with: "? $1", options: .regularExpression)
137	            result = result.replacingOccurrences(of: "!([A-Z])", with: "! $1", options: .regularExpression)
138	            
139	            // Clean up multiple spaces
140	            result = result.replacingOccurrences(of: "  +", with: " ", options: .regularExpression)
141	            
142	            return result.trimmingCharacters(in: .whitespacesAndNewlines)
143	        }
144	        
145	        func dataScanner(_ dataScanner: DataScannerViewController, becameUnavailableWithError error: DataScannerViewController.ScanningUnavailable) {
146	            parent.isScanning = false
147	        }
148	    }
149	}
