                        thumbnail(data)
                    }
                }
            }
        }

        if isLoading {
            HStack {
                ProgressView().controlSize(.small)
                Text("加载中…").foregroundStyle(.secondary)
            }
            .frame(maxWidth: .infinity)
        } else {
            HStack(spacing: 10) {
                // From the Photos library.
