import json, re

d = json.load(open('SwiftMandarin/Localizable.xcstrings'))
strings = d['strings']

def has_cjk(s): return any('一' <= ch <= '鿿' or '㐀' <= ch <= '䶿' for ch in s)
def has_latin_letters(s): return any(ch.isalpha() and ord(ch) < 0x250 for ch in s)

def val(entry, loc):
    l = entry.get('localizations',{}).get(loc)
    if not l: return None
    su = l.get('stringUnit')
    if not su: return None
    return su.get('value'), su.get('state')

need_zh = {}   # english-source keys missing chinese
need_en = {}   # chinese-source keys missing english
fmt_only = []  # no translation needed
already = {'zh':0,'en_for_cjk':0}

for k, entry in strings.items():
    if k == '': 
        fmt_only.append(k); continue
    cjk = has_cjk(k)
    latin = has_latin_letters(k)
    envv = val(entry,'en')
    zhv = val(entry,'zh-Hans')
    if cjk:
        # chinese source -> needs english
        if envv and envv[0] and envv[1]=='translated':
            already['en_for_cjk']+=1
        else:
            need_en[k] = {'cur_en': envv[0] if envv else None}
    else:
        # english source -> needs chinese unless format-only (no latin letters)
        if not latin:
            fmt_only.append(k); continue
        if zhv and zhv[0]:
            already['zh']+=1
        else:
            need_zh[k] = {}

print('TOTAL keys:', len(strings))
print('Already have zh (english keys):', already['zh'])
print('Already have en (chinese keys, translated):', already['en_for_cjk'])
print('Format-only / no-translation keys:', len(fmt_only))
print('NEED zh (english->chinese):', len(need_zh))
print('NEED en (chinese->english):', len(need_en))

out = {
  'need_zh': sorted(need_zh.keys()),
  'need_en': sorted(need_en.keys()),
}
json.dump(out, open('/tmp/translate_work.json','w'), ensure_ascii=False, indent=1)
print('wrote /tmp/translate_work.json')
print()
print('--- need_en (CJK keys, sample) ---')
for k in list(need_en.keys())[:40]: print('   ', repr(k))
"

