export const meta = {
  name: 'verify-translations',
  description: 'Adversarially review the bilingual String Catalog for translation accuracy, naturalness, and placeholder integrity',
  phases: [{ title: 'Review', detail: '10 batch reviewers + 1 consistency critic' }],
}

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    corrections: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          key: { type: 'string', description: 'The exact catalog key from the batch file' },
          lang: { type: 'string', enum: ['en', 'zh'], description: 'Which localization to fix' },
          current: { type: 'string', description: 'The current value being replaced' },
          suggested: { type: 'string', description: 'The corrected value (placeholders preserved verbatim)' },
          reason: { type: 'string' },
          severity: { type: 'string', enum: ['error', 'warning', 'nit'] },
        },
        required: ['key', 'lang', 'suggested', 'reason', 'severity'],
      },
    },
  },
  required: ['corrections'],
}

const guide = `This is the String Catalog for "SwiftMandarin", a macOS/iOS Mandarin<->English translation & learning app. It has English and Simplified Chinese (zh-Hans) UI versions.

For each entry: \`key\` is the source string, \`comment\` explains the UI context, \`en\` is what English mode shows (null means the key itself is the English text), \`zh\` is what Chinese mode shows.

Flag a correction ONLY for genuine problems:
- WRONG or unnatural translation (e.g. "More"->"多" should be "更多"; truncated/over-literal single-character renderings; mistranslations).
- WRONG LANGUAGE (English text left in the zh field, or Chinese left in the en field).
- PLACEHOLDER errors: every %@ / %lld / positional %1$lld %2$@ / \${token} / newline \\n / symbols (• → ↔ ·) MUST appear in the translation exactly as in the source, same count, correct positions. Missing/extra/renumbered placeholders are 'error'.
- Inconsistent terminology for the same concept across the app.
Do NOT nitpick acceptable synonyms or intentionally bilingual labels (e.g. "自动 · Auto"). Keep brand/technical names (OpenAI, Ollama, API Key, JSON, gpt-oss:20b, URLs) untranslated.
Severity: 'error' = wrong/broken (incl. placeholder), 'warning' = unnatural but understandable, 'nit' = minor polish. Return the exact \`key\` verbatim so corrections can be applied programmatically.`

phase('Review')

const reviewers = []
for (let n = 1; n <= 10; n++) {
  reviewers.push(() => agent(
    `${guide}\n\nRead the file /tmp/review_batches/batch_${n}.json (a JSON array of entries). Review EVERY entry for the problems above and return all needed corrections.`,
    { label: `review:batch${n}`, phase: 'Review', schema: SCHEMA, agentType: 'Explore' }
  ))
}

const critic = () => agent(
  `${guide}\n\nRead the file /tmp/review_all.json (the FULL catalog, ~549 entries). Your single job: find TERMINOLOGY INCONSISTENCIES — the same English concept translated differently into Chinese across entries (e.g. "Vocabulary" rendered as 词汇/生词本/词汇本 in different places, or "Settings" inconsistently). Recommend a single canonical Chinese term and return corrections (lang:"zh") for the entries that should change to match it. Also flag any zh value that still contains untranslated English words (other than brand/technical names) or any placeholder mismatch you notice.`,
  { label: 'consistency-critic', phase: 'Review', schema: SCHEMA, agentType: 'Explore' }
)

const results = await parallel([...reviewers, critic])
const corrections = results.filter(Boolean).flatMap(r => r.corrections || [])
log(`collected ${corrections.length} proposed corrections`)
return { corrections }

