457	        guard !imageProviders.isEmpty else { return false }
458	
459	        switch target {
460	        case .workbook: isLoadingWorkbook = true
461	        case .answers: isLoadingAnswers = true
462	        }
463	
464	        Task {
465	            var datas: [Data] = []
466	            for provider in imageProviders {
467	                if let data = await Self.loadImageData(from: provider) {
468	                    datas.append(downscaledJPEG(data))
469	                }
470	            }
471	            await MainActor.run {
472	                switch target {
473	                case .workbook:
474	                    workbookImages.append(contentsOf: datas)
475	                    isLoadingWorkbook = false
476	                case .answers:
477	                    answerImages.append(contentsOf: datas)
478	                    isLoadingAnswers = false
479	                }
480	            }
481	        }
482	        return true
483	    }
484	
485	    private static func loadImageData(from provider: NSItemProvider) async -> Data? {
486	        await withCheckedContinuation { continuation in
487	            provider.loadDataRepresentation(forTypeIdentifier: UTType.image.identifier) { data, _ in
488	                continuation.resume(returning: data)
489	            }
490	        }
491	    }
492	
493	    private func grade() async {
494	        await MainActor.run {
495	            isGrading = true
496	            errorMessage = nil
497	            result = nil
498	            savedQuestionIDs = []
499	        }
500	        do {
501	            let graded = try await AIWordExplanationService.shared.gradeWorkbook(
502	                workbookImages: workbookImages,
503	                answerImages: answerImages,
504	                customInstructions: customInstructions.isEmpty ? nil : customInstructions
505	            )
506	            await MainActor.run {
507	                result = graded
508	                isGrading = false
509	            }
510	        } catch {
511	            await MainActor.run {
512	                errorMessage = error.localizedDescription
513	                isGrading = false
514	            }
515	        }
516	    }
517	
518	    private func saveVocab(for question: GradedQuestion) {
519	        Task {
520	            if await saveVocabItem(vocabItem(for: question)) {
521	                await MainActor.run { savedQuestionIDs.insert(question.id) }
522	            }
523	        }
524	    }
525	
526	    private func saveAllWrongVocab() {
527	        guard let result else { return }
528	        let questions = result.wrongQuestions
529	        Task {
530	            for question in questions {
531	                if await saveVocabItem(vocabItem(for: question)) {
532	                    await MainActor.run { savedQuestionIDs.insert(question.id) }
533	                }
534	            }
535	        }
536	    }
537	
538	    /// The word to save for a wrong answer: the model's vocab item if usable,
539	    /// otherwise built from the correct answer so nothing is ever lost.
540	    private func vocabItem(for question: GradedQuestion) -> ExtractedVocabItem {
541	        if let v = question.vocab {
542	            let t = v.term.trimmingCharacters(in: .whitespacesAndNewlines)
543	            let m = v.meaning.trimmingCharacters(in: .whitespacesAndNewlines)
544	            if !t.isEmpty || !m.isEmpty { return v }
545	        }
546	        return ExtractedVocabItem(term: question.correctAnswer, reading: "", meaning: "")
547	    }
548	
549	    /// Save a wrong-answer word to the vocabulary store. The store keys on the
550	    /// Chinese field, so: use whichever side is Chinese; if neither is, translate
551	    /// the English term to Chinese; as a last resort keep the word as-is rather
552	    /// than silently dropping it. Returns true when a save was attempted.
553	    @discardableResult
554	    private func saveVocabItem(_ item: ExtractedVocabItem) async -> Bool {
555	        let term = item.term.trimmingCharacters(in: .whitespacesAndNewlines)
556	        let meaning = item.meaning.trimmingCharacters(in: .whitespacesAndNewlines)
557	        guard !term.isEmpty || !meaning.isEmpty else { return false }
558	
559	        let termIsChinese = term.contains { $0.isChineseCharacter }
560	        let meaningIsChinese = meaning.contains { $0.isChineseCharacter }
561	
562	        var chinese: String
563	        var definition: String
564	        if termIsChinese {
565	            chinese = term
566	            definition = meaning
567	        } else if meaningIsChinese {
568	            chinese = meaning
569	            definition = term
570	        } else {
571	            // Neither side is Chinese — translate the (English) term to Chinese.
572	            let english = term.isEmpty ? meaning : term
573	            definition = english
574	            if let zh = try? await WordTranslationService.shared.translateToChinese(english),
575	               zh.contains(where: { $0.isChineseCharacter }) {
576	                chinese = zh
577	            } else {
578	                chinese = english  // last resort: keep the word rather than drop it
579	            }
580	        }
581	
582	        let key = chinese.trimmingCharacters(in: .whitespacesAndNewlines)
583	        guard !key.isEmpty else { return false }
584	        let pinyin = key.contains(where: { $0.isChineseCharacter })
585	            ? (item.reading.isEmpty ? PinyinConverter.convert(key) : item.reading)
586	            : ""
587	        let def = definition.isEmpty ? key : definition
588	
589	        await MainActor.run {
590	            if !savedTermsStore.contains(chinese: key) {
591	                savedTermsStore.add(SavedTerm(chinese: key, pinyin: pinyin, definition: def, partOfSpeech: "phrase"))
592	            }
593	        }
594	        return true
595	    }
596	}
597	
598	// MARK: - Graded Question Card
599	
600	private struct GradedQuestionCard: View {
601	    let question: GradedQuestion
602	    let isSaved: Bool
603	    let onSaveVocab: () -> Void
604	
605	    var body: some View {
606	        VStack(alignment: .leading, spacing: 10) {
607	            HStack(alignment: .top) {
608	                Image(systemName: question.isCorrect ? "checkmark.circle.fill" : "xmark.circle.fill")
609	                    .foregroundStyle(question.isCorrect ? .green : .red)
610	                    .font(.title3)
611	                VStack(alignment: .leading, spacing: 2) {
612	                    if !question.questionNumber.isEmpty {
613	                        Text("第 \(question.questionNumber) 题")
614	                            .font(.caption)
615	                            .foregroundStyle(.secondary)
616	                    }
617	                    if !question.question.isEmpty {
618	                        Text(question.question)
619	                            .font(.body)
620	                            .fontWeight(.medium)
621	                    }
622	                }
623	                Spacer()
624	            }
625	
626	            if !question.studentAnswer.isEmpty {
627	                answerRow(label: "你的答案", value: question.studentAnswer,
628	                          color: question.isCorrect ? .green : .red)
629	            }
630	            if !question.isCorrect, !question.correctAnswer.isEmpty {
631	                answerRow(label: "正确答案", value: question.correctAnswer, color: .green)
632	            }
633	            if !question.explanation.isEmpty {
634	                Text(question.explanation)
635	                    .font(.caption)
636	                    .foregroundStyle(.secondary)
637	            }
638	
639	            if !question.isCorrect, let vocab = question.vocab,
640	               !vocab.term.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
641	                Divider()
642	                HStack {
643	                    VStack(alignment: .leading, spacing: 2) {
644	                        Text(vocab.term).font(.subheadline).fontWeight(.medium)
645	                        if !vocab.reading.isEmpty {
646	                            Text(vocab.reading).font(.caption).foregroundStyle(.secondary)
647	                        }
648	                        if !vocab.meaning.isEmpty {
649	                            Text(vocab.meaning).font(.caption).foregroundStyle(.secondary)
650	                        }
651	                    }
652	                    Spacer()
653	                    Button {
654	                        onSaveVocab()
655	                    } label: {
656	                        Label(isSaved ? "已保存" : "保存", systemImage: isSaved ? "bookmark.fill" : "bookmark")
657	                    }
658	                    .buttonStyle(.bordered)
659	                    .controlSize(.small)
660	                    .disabled(isSaved)
661	                }
662	            }
663	        }
664	        .padding()
665	        .background(
666	            RoundedRectangle(cornerRadius: 14)
667	                .fill(.background)
668	                .shadow(color: .black.opacity(0.05), radius: 6, y: 3)
669	        )
670	        .overlay(
671	            RoundedRectangle(cornerRadius: 14)
672	                .stroke((question.isCorrect ? Color.green : Color.red).opacity(0.25), lineWidth: 1)
673	        )
674	    }
675	
676	    private func answerRow(label: String, value: String, color: Color) -> some View {
677	        HStack(alignment: .firstTextBaseline, spacing: 8) {
678	            Text(label)
679	                .font(.caption)
680	                .foregroundStyle(.secondary)
