688	
689	// MARK: - Cross-platform image helpers
690	
691	private func imageFromData(_ data: Data) -> Image? {
692	#if canImport(UIKit)
693	    return UIImage(data: data).map { Image(uiImage: $0) }
694	#elseif canImport(AppKit)
695	    return NSImage(data: data).map { Image(nsImage: $0) }
696	#else
697	    return nil
698	#endif
699	}
700	
701	/// Downscale and JPEG-compress image data via ImageIO so multi-image requests
702	/// stay within reasonable payload/token limits. Applies EXIF orientation.
703	private func downscaledJPEG(_ data: Data, maxDimension: Int = 1536, quality: CGFloat = 0.7) -> Data {
704	    guard let source = CGImageSourceCreateWithData(data as CFData, nil) else { return data }
705	    let options: [CFString: Any] = [
706	        kCGImageSourceCreateThumbnailFromImageAlways: true,
707	        kCGImageSourceCreateThumbnailWithTransform: true,
708	        kCGImageSourceThumbnailMaxPixelSize: maxDimension,
709	    ]
710	    guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else { return data }
711	    let output = NSMutableData()
712	    guard let destination = CGImageDestinationCreateWithData(output, UTType.jpeg.identifier as CFString, 1, nil) else {
713	        return data
714	    }
715	    CGImageDestinationAddImage(destination, cgImage, [kCGImageDestinationLossyCompressionQuality: quality] as CFDictionary)
716	    guard CGImageDestinationFinalize(destination) else { return data }
717	    return output as Data
718	}
