import json, collections, re
CAT='SwiftMandarin/Localizable.xcstrings'
d=json.load(open(CAT),object_pairs_hook=collections.OrderedDict)
s=d['strings']
ADD={
 'App Language':'应用语言',
 'Language':'语言',
 'Switch the entire app between the English and Mandarin versions.':'在英文版和中文版之间切换整个应用。',
}
for k,zh in ADD.items():
    e=s.setdefault(k,collections.OrderedDict())
    locs=e.setdefault('localizations',collections.OrderedDict())
    locs['zh-Hans']=collections.OrderedDict([('stringUnit',collections.OrderedDict([('state','translated'),('value',zh)]))])

def canon(entry):
    out=collections.OrderedDict()
    for ek in sorted(entry.keys()):
        val=entry[ek]
        if ek=='localizations':
            locs=collections.OrderedDict()
            for lk in sorted(val.keys()):
                su=val[lk].get('stringUnit')
                if su is not None:
                    val[lk]['stringUnit']=collections.OrderedDict([('state',su['state']),('value',su['value'])])
                locs[lk]=collections.OrderedDict(sorted(val[lk].items()))
            out[ek]=locs
        else: out[ek]=val
    return out
for k in list(s.keys()): s[k]=canon(s[k])
with open(CAT,'w') as f:
    json.dump(d,f,ensure_ascii=False,indent=2,separators=(',',' : ')); f.write('\n')

# FULL coverage + placeholder recheck
s=json.load(open(CAT))['strings']
TOKEN=re.compile(r'%\d+\$@|%\d+\$lld|%@|%lld|%%|\$\{[^}]+\}')
def toks(v):
    t=[re.sub(r'%\d+\$','%',x) for x in TOKEN.findall(v or '')]
    c=collections.Counter(t); c['\\n']=(v or '').count('\n'); return c
def has_cjk(x): return any('一'<=c<='鿿' for c in x)
def en(k): return s[k].get('localizations',{}).get('en',{}).get('stringUnit',{}).get('value')
def zh(k): return s[k].get('localizations',{}).get('zh-Hans',{}).get('stringUnit',{}).get('value')
gaps=[]; ph=[]
def translatable(k): return any(ch.isalpha() and ord(ch)<0x250 for ch in k) or has_cjk(k)
for k,e in s.items():
    if not k.strip(): continue
    z=zh(k); ev=en(k)
    if z is not None and toks(z)!=toks(k): ph.append(('zh',k))
    if ev is not None and toks(ev)!=toks(k): ph.append(('en',k))
    zh_ok = (z is not None) or (not translatable(k)) or (not has_cjk(k) and not any(ch.isalpha() and ord(ch)<0x250 for ch in k))
    en_ok = (ev is not None) or (not has_cjk(k))
    # a translatable English-source key needs zh; CJK key needs en
    needs_zh = (not has_cjk(k)) and any(ch.isalpha() and ord(ch)<0x250 for ch in k)
    if needs_zh and z is None: gaps.append(('zh',k))
    if has_cjk(k) and ev is None: gaps.append(('en',k))
print('total keys:', len([k for k in s if k.strip()]))
print('coverage gaps:', gaps)
print('placeholder errors:', ph)
PYEOF

