import json, re, collections
s=json.load(open('SwiftMandarin/Localizable.xcstrings'))['strings']
TOKEN=re.compile(r'%\d+\$@|%\d+\$lld|%@|%lld|%%|\$\{[^}]+\}')
def toks(v):
    t=[re.sub(r'%\d+\$','%',x) for x in TOKEN.findall(v or '')]
    c=collections.Counter(t); c['\\n']=(v or '').count('\n'); return c
def has_cjk(x): return any('一'<=c<='鿿' for c in x)
def en(k): return s[k].get('localizations',{}).get('en',{}).get('stringUnit',{}).get('value')
def zh(k): return s[k].get('localizations',{}).get('zh-Hans',{}).get('stringUnit',{}).get('value')
gaps=[]; ph=[]
for k,e in s.items():
    if not k.strip(): continue
    z=zh(k); ev=en(k)
    if z is not None and toks(z)!=toks(k): ph.append(('zh',k))
    if ev is not None and toks(ev)!=toks(k): ph.append(('en',k))
    needs_zh=(not has_cjk(k)) and any(ch.isalpha() and ord(ch)<0x250 for ch in k)
    if needs_zh and z is None: gaps.append(('zh',k))
    if has_cjk(k) and ev is None: gaps.append(('en',k))
print('total keys:', len([k for k in s if k.strip()]))
print('coverage gaps:', gaps)
print('placeholder errors:', ph)
# git changed swift files
PYEOF
echo "=== changed files ==="
